#!/usr/bin/env python3
import base64,datetime as dt,hashlib,json,os,pathlib,shutil,sqlite3,subprocess,sys,tempfile,time,urllib.request,urllib.error
APP=pathlib.Path('/opt/umraniye-osint-deneme')
X=pathlib.Path('/opt/umraniye-osint-x-twscrape-deneme')
STATE=pathlib.Path('/var/lib/umraniye-osint-x-backup')
SITE='umraniye-osint-deneme.service'
TIMER='umraniye-osint-x-twscrape-deneme.timer'
PUB='umraniye-osint-x-backup-publish.service'
EXPECTED='d923a697eb42d95634015fd1373f8d7cf50c134ccd1becb0b8f82a87ab207b58'
PAYLOAD={'browser-research.next.mjs': '', 'publish.py': '', 'publish.service': '', 'collector.timer': '', 'collector.conf': 'W1NlcnZpY2VdDQpFeGVjU3RhcnRQb3N0PSsvdXNyL2Jpbi9zeXN0ZW1jdGwgLS1uby1ibG9jayBzdGFydCB1bXJhbml5ZS1vc2ludC14LWJhY2t1cC1wdWJsaXNoLnNlcnZpY2UNCg==', 'test_backend.mjs': '', 'test_publish.py': ''}

def run(args,timeout=30):return subprocess.run(args,capture_output=True,text=True,timeout=timeout)
def write(path,data):
 path.parent.mkdir(parents=True,exist_ok=True);tmp=path.with_name(path.name+'.tmp');tmp.write_bytes(data);tmp.chmod(0o644);tmp.replace(path)
def health():
 for i in range(25):
  try:
   with urllib.request.build_opener(urllib.request.ProxyHandler({})).open('http://127.0.0.1:3001/giris',timeout=3) as r:
    if r.status==200:return True
  except Exception:pass
  time.sleep(1)
 return False

def main():
 if os.geteuid()!=0:raise RuntimeError('sudo_required')
 target=APP/'server/browser-research.mjs'
 if target.is_symlink() or X.is_symlink() or STATE.is_symlink():raise RuntimeError('symlink_denied')
 if hashlib.sha256(target.read_bytes()).hexdigest()!=EXPECTED:raise RuntimeError('source_version_changed_no_install')
 collector='umraniye-osint-x-twscrape-deneme.service'
 if run(['systemctl','show',collector,'--property=ActiveState','--value']).stdout.strip() in ('active','activating'):raise RuntimeError('shadow_round_running_no_changes')
 timerpath=pathlib.Path('/etc/systemd/system')/TIMER
 pubpath=pathlib.Path('/etc/systemd/system')/PUB
 drop=pathlib.Path('/etc/systemd/system')/(collector+'.d/zz-backup-publish.conf')
 if any(p.exists() for p in [timerpath,pubpath,drop]):raise RuntimeError('backup_units_already_exist')
 # Verify production service is not restarted by this installation.
 prodBefore=run(['systemctl','show','umraniye-osint.service','--property=ExecMainStartTimestampMonotonic','--value']).stdout.strip()
 backup=pathlib.Path('/var/lib/umraniye-osint-deneme/backups')/('x-backup-bridge-'+dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ'));backup.mkdir(parents=True,mode=0o700)
 files={target:base64.b64decode(PAYLOAD['browser-research.next.mjs']),X/'backup_publish.py':base64.b64decode(PAYLOAD['publish.py']),pubpath:base64.b64decode(PAYLOAD['publish.service']),timerpath:base64.b64decode(PAYLOAD['collector.timer']),drop:base64.b64decode(PAYLOAD['collector.conf'])}
 old={str(p):base64.b64encode(p.read_bytes()).decode() if p.exists() else None for p in files}
 rollback="""#!/usr/bin/env python3
import base64,pathlib,subprocess
OLD=__OLD__
subprocess.run(['systemctl','disable','--now','umraniye-osint-x-twscrape-deneme.timer'],capture_output=True)
subprocess.run(['systemctl','stop','umraniye-osint-x-backup-publish.service'],capture_output=True)
for name,value in OLD.items():
 p=pathlib.Path(name)
 if value is None:p.unlink(missing_ok=True)
 else:p.write_bytes(base64.b64decode(value));p.chmod(0o644)
subprocess.run(['systemctl','daemon-reload'],check=True)
subprocess.run(['systemctl','restart','umraniye-osint-deneme.service'],check=True)
print('X yedek aktarimi geri alindi; kayitlar ve oturumlar korundu.')
""".replace('__OLD__',repr(old))
 (backup/'geri-al.py').write_text(rollback)
 # Online backup before any live writes; no replay/reset of queues.
 con=sqlite3.connect('file:/var/lib/umraniye-osint-deneme/osint.sqlite?mode=ro',uri=True)
 saved=sqlite3.connect(backup/'osint.sqlite');con.backup(saved);saved.close();con.close()
 with tempfile.TemporaryDirectory(prefix='x-bridge-check-') as d:
  stage=pathlib.Path(d);write(stage/'publish.py',base64.b64decode(PAYLOAD['publish.py']));write(stage/'test_publish.py',base64.b64decode(PAYLOAD['test_publish.py']))
  test=run(['python3',str(stage/'test_publish.py')],60)
  if test.returncode:raise RuntimeError('publisher_tests_failed_no_install')
  # Full real import graph, independent temporary source copy, fake test DB only.
  clone=stage/'application';clone.mkdir()
  for folder,dirs,names in os.walk(APP,followlinks=False):
   dirs[:]=[n for n in dirs if not n.startswith('.') and n not in {'node_modules','backups','data','logs','profiles','venv'} and not (pathlib.Path(folder)/n).is_symlink()]
   for name in names:
    src=pathlib.Path(folder)/name
    if not src.is_symlink() and (src.suffix in {'.mjs','.js','.cjs','.html','.png'} or name=='package.json'):
     dest=clone/src.relative_to(APP);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(src,dest)
  write(clone/'server/browser-research.mjs',files[target]);write(stage/'test_backend.mjs',base64.b64decode(PAYLOAD['test_backend.mjs']))
  test=run(['node',str(stage/'test_backend.mjs'),str(clone/'server/browser-research.mjs')],60)
  if test.returncode:
   # This is an isolated fixture run, never a live credential-bearing request.
   detail=(test.stderr or test.stdout)[-2500:]
   (backup/'backend-test-failure.txt').write_text(detail)
   print('Backend kontrol ayrintisi: '+str(backup/'backend-test-failure.txt'))
   raise RuntimeError('backend_tests_failed_no_install')
 STATE.mkdir(mode=0o700,exist_ok=True);STATE.chmod(0o700)
 changed=False
 try:
  changed=True
  for p,data in files.items():write(p,data)
  check=run(['systemd-analyze','verify',str(pubpath),str(timerpath)])
  if check.returncode:raise RuntimeError('unit_validation_failed')
  if run(['systemctl','daemon-reload']).returncode:raise RuntimeError('daemon_reload_failed')
  if run(['systemctl','restart',SITE],60).returncode or not health():raise RuntimeError('application_health_failed')
  result=run(['systemctl','start',PUB],100)
  report=json.loads((STATE/'report.json').read_text()) if (STATE/'report.json').exists() else {'status':'publisher_report_missing'}
  verified=report.get('confirmedInExistingStorage',0)>0
  if verified and result.returncode==0:
   if run(['systemctl','enable','--now',TIMER]).returncode:raise RuntimeError('timer_enable_failed')
  else:
   # No unverified collector is automatically enabled. Keep manual bridge available.
   drop.unlink(missing_ok=True);timerpath.unlink(missing_ok=True);run(['systemctl','daemon-reload'])
  prodAfter=run(['systemctl','show','umraniye-osint.service','--property=ExecMainStartTimestampMonotonic','--value']).stdout.strip()
  output={'result':'x_backup_connected' if verified else 'x_backup_bridge_installed_verification_pending','backupEnabled':verified,'interval':'7 minutes after completed collection + up to 30 seconds scheduling spread' if verified else None,'existingXReaderChanged':False,'browserHealthPreserved':True,'samePostUsesExistingIdentity':True,'localFreshnessMinutes':60,'historicalReplay':False,'telegramSettingsChanged':False,'testMessageSent':False,'productionServiceUnchanged':prodBefore==prodAfter,'applicationLocalHealthVerified':True,'externalBrowserVerified':False,'publisher':report,'backup':str(backup),'rollback':'sudo python3 '+str(backup/'geri-al.py')}
  (STATE/'installation-report.json').write_text(json.dumps(output,ensure_ascii=False,indent=2));print(json.dumps(output,ensure_ascii=False,indent=2))
 except Exception:
  if changed:run(['python3',str(backup/'geri-al.py')],90)
  raise

if __name__=='__main__':
 try:main()
 except Exception as exc:print('KURULAMADI: '+(str(exc) if isinstance(exc,RuntimeError) else type(exc).__name__));sys.exit(1)
